    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Integer id;
    @Column(name = "ten_ram")
    private String tenRam;
    @Column(name = "dung_luong_ram")
    private String dungLuongRam;
    @Column(name = "trang_thai")
    private Integer trangThai;
}

